#!/usr/bin/env node
import fs from 'node:fs';
import path from 'node:path';
import zlib from 'node:zlib';

const payload={"package.json":"","README.md":"","RELEASE_NOTES.md":"","RELEASE_NOTES_0.23.md":"","README_NASADENIE_0.23.txt":"","MANAGEMENT_INTELLIGENCE_0.23.md":"","src/App.tsx":"","src/views/DepartmentPortal.tsx":"","src/views/TechnologyCatalog.tsx":"","src/views/ItCosts.tsx":"","src/views/OperationsIntelligence.tsx":"","src/views/OperationsIntelligence.css":"","src/lib/managementIntelligence.ts":"","src/lib/storage.ts":"","src/data/seed.json":"","src/data/contractPayments.json":""};
const target=process.cwd();
const stamp=new Date().toISOString().replace(/[:.]/g,'-');
const backup=path.join(target,`backup-before-v0230-${stamp}`);
function fail(message){console.error('ERROR:',message);process.exit(1)}
let pkg={};
try{pkg=JSON.parse(fs.readFileSync(path.join(target,'package.json'),'utf8'))}catch{fail('package.json sa nepodarilo nacitat. Spusti installer v koreni projektu.')}
if(pkg.name!=='is-riadenie-odboru') fail('Tento priecinok nevyzera ako projekt is-riadenie-odboru.');
console.log('IS Riadenie odboru - upgrade na v0.23.0');
console.log('Aktualna verzia:',pkg.version||'nezistena');
if(pkg.version && pkg.version!=='0.22.0') console.log('UPOZORNENIE: installer bol otestovany primarne pre upgrade z v0.22.0.');
fs.mkdirSync(backup,{recursive:true});
let written=0,backed=0;
for(const [rel,encoded] of Object.entries(payload)){
  const destination=path.join(target,rel);
  if(fs.existsSync(destination)){
    const backupPath=path.join(backup,rel);
    fs.mkdirSync(path.dirname(backupPath),{recursive:true});
    fs.copyFileSync(destination,backupPath);backed++;
  }
  fs.mkdirSync(path.dirname(destination),{recursive:true});
  fs.writeFileSync(destination,zlib.gunzipSync(Buffer.from(encoded,'base64')));written++;
  console.log('WRITE',rel);
}
for(const cache of ['dist','.vite',path.join('node_modules','.vite')]){const full=path.join(target,cache);if(fs.existsSync(full)){fs.rmSync(full,{recursive:true,force:true});console.log('CLEAR',cache)}}
const installed=JSON.parse(fs.readFileSync(path.join(target,'package.json'),'utf8'));
if(installed.version!=='0.23.0') fail('Kontrola verzie zlyhala.');
const app=fs.readFileSync(path.join(target,'src/App.tsx'),'utf8');
const intelligence=fs.readFileSync(path.join(target,'src/views/OperationsIntelligence.tsx'),'utf8');
const engine=fs.readFileSync(path.join(target,'src/lib/managementIntelligence.ts'),'utf8');
const payments=JSON.parse(fs.readFileSync(path.join(target,'src/data/contractPayments.json'),'utf8'));
if(!app.includes("view==='intelligence'")) fail('Riadiace centrum nie je zapojene do App.tsx.');
if(!intelligence.includes('SERVICE 360')||!intelligence.includes('Lifecycle radar')||!intelligence.includes('Dodávatelia / zmluvy')) fail('Operations Intelligence UI sa nepodarilo overit.');
if(!engine.includes('buildControlTower')||!engine.includes('contractForecast')) fail('Management Intelligence engine sa nepodarilo overit.');
const a=payments?.meta?.authoritativeSpent||{},c=payments?.meta?.calculatedSpent||{};
for(const code of ['10','22','25']) if(Math.abs(Number(a[code]||0)-Number(c[code]||0))>0.01) fail(`Kontrola riadkovych platieb ulohy ${code} zlyhala.`);
console.log('');
console.log(`VERIFIED: v0.23.0 nainstalovana. Suborov zapisanych: ${written}, zalohovanych: ${backed}.`);
console.log('Zaloha:',backup);
console.log('Nasledne spusti npm run build alebo bezny Vercel deployment.');
